import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        n = int(next(iterator))
        m = int(next(iterator))
        w = int(next(iterator))
    except StopIteration:
        return

    grid = []
    for _ in range(n):
        row = []
        for _ in range(m):
            row.append(int(next(iterator)))
        grid.append(row)

    # BFS for distance without portals
    def bfs(start_node, dist_matrix):
        queue = deque([start_node])
        r, c = start_node
        dist_matrix[r][c] = 0

        directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

        while queue:
            curr_r, curr_c = queue.popleft()
            current_dist = dist_matrix[curr_r][curr_c]

            for dr, dc in directions:
                nr, nc = curr_r + dr, curr_c + dc

                if 0 <= nr < n and 0 <= nc < m:
                    if grid[nr][nc] != -1:
                        if dist_matrix[nr][nc] == -1:
                            dist_matrix[nr][nc] = current_dist + w
                            queue.append((nr, nc))

    # Distance from start (0, 0)
    dist_start = [[-1] * m for _ in range(n)]
    bfs((0, 0), dist_start)

    # Distance to end (n-1, m-1)
    dist_end = [[-1] * m for _ in range(n)]
    # We run BFS backwards from the destination to find distances to all reachable cells
    bfs((n - 1, m - 1), dist_end)

    ans = dist_start[n - 1][m - 1]

    # Check portal paths
    min_portal_cost_from_start = float('inf')
    min_portal_cost_to_end = float('inf')

    # Find min cost to reach any portal from start
    # And min cost to reach any portal from end (which is effectively reaching end from that portal)

    # We need to iterate over all cells to check portals
    for i in range(n):
        for j in range(m):
            val = grid[i][j]
            if val > 0:  # It's a portal
                if dist_start[i][j] != -1:
                    cost = dist_start[i][j] + val
                    if cost < min_portal_cost_from_start:
                        min_portal_cost_from_start = cost

                if dist_end[i][j] != -1:
                    cost = dist_end[i][j] + val
                    if cost < min_portal_cost_to_end:
                        min_portal_cost_to_end = cost

    if min_portal_cost_from_start != float('inf') and min_portal_cost_to_end != float('inf'):
        portal_path_cost = min_portal_cost_from_start + min_portal_cost_to_end
        if ans == -1 or portal_path_cost < ans:
            ans = portal_path_cost

    print(ans)

if __name__ == '__main__':
    solve()
